 "content": "from collections import Counter
from math import gcd
from functools import reduce


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = {color for color, _ in counts.most_common(2)}
    marked = set(counts) - background
    if not marked:
        return grid

    def lattice(coords, limit):
        coords = sorted(set(coords))
        if len(coords) < 2:
            return coords
        step = reduce(gcd, (b - a for a, b in zip(coords, coords[1:])))
        phase = coords[0] % step
        return [i for i in range(limit) if i % step == phase]

    rows = lattice([r for r in range(h) if any(v in marked for v in grid[r])], h)
    cols = lattice([c for c in range(w) if any(grid[r][c] in marked for r in range(h))], w)
    if len(rows) < 2 or len(cols) < 2:
        return []

    fill = grid[(rows[0] + rows[1]) // 2][(cols[0] + cols[1]) // 2]
    out = []
    for r0, r1 in zip(rows, rows[1:]):
        out_row = []
        for c0, c1 in zip(cols, cols[1:]):
            corners = (grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1])
            color = corners[0]
            out_row.append(color if color in marked and all(v == color for v in corners) else fill)
        out.append(out_row)

    # Remove empty exterior bands while preserving empty bands inside the pattern.
    while out and all(v == fill for v in out[0]):
        out.pop(0)
    while out and all(v == fill for v in out[-1]):
        out.pop()
    while out and out[0] and all(row[0] == fill for row in out):
        for row in out:
            row.pop(0)
    while out and out[0] and all(row[-1] == fill for row in out):
        for row in out:
            row.pop()
    return out
